//! 2026-10-14: [`defined_globals`] on the forms nvcc emits for this tree's kernels (copied
//! from the gb10 PTX), and on the lines that mention a symbol without defining it.

use super::defined_globals;

/// 2026-10-14: A PTX module laid out the way nvcc writes one: the `.globl` comment, the
/// definitions, then a kernel that loads and stores global memory.
const MODULE: &str = "\
//
// Generated by NVIDIA NVVM Compiler
.version 9.0
.target sm_121a
.address_size 64

\t// .globl\tw4a16_gemm
.global .align 4 .u32 w4a16_gemm_n_tile = 64;
.global .align 4 .u32 w4a16_gemm_t_n_tile = 64;
.global .align 4 .u32 bare_counter;
.global .align 4 .b8 scratch_words[64];
.global .align 1 .b8 $str$1[6] = {37, 100, 10, 0, 0, 0};
.const .align 4 .b8 lut_e2m1[64] = {0, 0, 0, 0};
.visible .global .align 4 .u32 vis_a_e4m3 = 1;
.weak .global .align 4 .u32 weak_n_tile = 32;
.extern .global .align 4 .u32 elsewhere_n_tile;
.shared .align 4 .b8 tile_smem[1024];

.entry w4a16_gemm(
\t.param .u64 w4a16_gemm_param_0
)
{
\t.reg .b32 \t%r<4>;
\tld.global.u32 \t%r1, [w4a16_gemm_n_tile];
\tst.global.u32 \t[bare_counter], %r1;
\tret;
}
";

#[test]
fn every_definition_form_is_listed() {
    let g = defined_globals(MODULE);
    for name in [
        "w4a16_gemm_n_tile",
        "w4a16_gemm_t_n_tile",
        "bare_counter",
        "scratch_words",
        "$str$1",
        "lut_e2m1",
        "vis_a_e4m3",
        "weak_n_tile",
    ] {
        assert!(g.contains(name), "{name} missing from {g:?}");
    }
}

#[test]
fn nothing_but_definitions_is_listed() {
    let mut g: Vec<_> = defined_globals(MODULE).into_iter().collect();
    g.sort();
    assert_eq!(
        g,
        [
            "$str$1",
            "bare_counter",
            "lut_e2m1",
            "scratch_words",
            "vis_a_e4m3",
            "w4a16_gemm_n_tile",
            "w4a16_gemm_t_n_tile",
            "weak_n_tile",
        ],
        "an .extern declaration, a .shared variable, the kernel, its parameter, the \
         .globl comment and ld/st operands are not definitions"
    );
}

#[test]
fn a_module_without_variables_lists_none() {
    assert!(defined_globals(".version 9.0\n.entry k()\n{\n\tret;\n}\n").is_empty());
    assert!(defined_globals("").is_empty());
}

#[test]
fn a_truncated_definition_lists_nothing() {
    assert!(defined_globals(".global .align 4 .u32").is_empty());
    assert!(defined_globals(".global .align").is_empty());
    assert!(defined_globals(".const").is_empty());
}
